<script setup lang="ts">
import type { Location } from '~/types/api'
import { useApi } from '~/composables/useApi'
import { money } from '~/utils/format'
const api = useApi()
const provinces = ref<Location[]>([])
const districts = ref<Location[]>([])
const neighborhoods = ref<Location[]>([])
const provinceId = ref<number | undefined>()
const districtId = ref<number | undefined>()
const neighborhoodId = ref<number | undefined>()
const propertyType = ref('apartment')
const area = ref(100)
const areaType = ref<'net'|'gross'>('net')
const roomCount = ref<number | undefined>()
const isResidential = computed(() => ['apartment', 'detached_house', 'villa'].includes(propertyType.value))
watch(propertyType, () => { result.value = null; if (!isResidential.value) roomCount.value = undefined })
const loading = ref(false)
const loadingLocations = ref(false)
const error = ref('')
const result = ref<Record<string, any> | null>(null)
onMounted(async () => { loadingLocations.value=true; try { provinces.value=await api.locations({level:'province',limit:500}) } catch(e) { error.value=e instanceof Error?e.message:'İl listesi alınamadı.' } finally { loadingLocations.value=false } })
watch(provinceId, async (id) => { districtId.value=undefined; neighborhoodId.value=undefined; districts.value=[]; neighborhoods.value=[]; result.value=null; if(!id)return; try{districts.value=await api.locations({level:'district',parent_id:id,limit:500})}catch(e){error.value=e instanceof Error?e.message:'İlçeler alınamadı.'} })
watch(districtId, async (id) => { neighborhoodId.value=undefined; neighborhoods.value=[]; result.value=null; if(!id)return; try{neighborhoods.value=await api.locations({level:'neighborhood',parent_id:id,limit:500})}catch(e){error.value=e instanceof Error?e.message:'Mahalleler alınamadı.'} })
async function estimate(){ error.value=''; result.value=null; if(!provinceId.value||!districtId.value||!neighborhoodId.value){error.value='İl, ilçe ve mahalle seçmelisiniz.';return} if(!area.value||area.value<=0){error.value='Geçerli bir m² değeri girin.';return} loading.value=true; try{ result.value=await api.valuation({province_id:provinceId.value,district_id:districtId.value,neighborhood_id:neighborhoodId.value,property_type:propertyType.value,area_m2:area.value,area_type:isResidential.value?areaType.value:'parcel',room_count:isResidential.value?roomCount.value:undefined}) }catch(e){error.value=e instanceof Error?e.message:'Değerleme yapılamadı.'}finally{loading.value=false} }
</script>
<template>
<div class="page-heading"><div><p class="eyebrow">ANALİZ / DEĞERLEME</p><h1>Emsal ilanlarla ön değer tahmini</h1><p>Konumu ve gayrimenkul özelliklerini seçin; sistem önce mahalledeki aktif benzer ilanları, yeterli emsal yoksa aynı ilçedeki ilanları analiz eder. Konut, arsa ve tarla desteklenir.</p></div></div>
<div class="alert alert-warning">Tahmin yalnızca veritabanına kayıtlı aktif ilan fiyatlarına dayanır; gerçekleşmiş satış veya resmî ekspertiz değildir. Sistemde emsal ilan yoksa yapay bir fiyat üretilmez.</div>
<div v-if="error" class="alert alert-warning">{{ error }}</div>
<div class="dashboard-grid" style="grid-template-columns:minmax(0,1fr) minmax(280px,.85fr)"><section class="panel"><h2>Gayrimenkul bilgileri</h2>
<div class="field"><label>İl</label><select v-model.number="provinceId"><option :value="undefined">İl seçin</option><option v-for="p in provinces" :key="p.id" :value="p.id">{{ p.name }}</option></select></div>
<div class="field"><label>İlçe</label><select v-model.number="districtId" :disabled="!provinceId"><option :value="undefined">İlçe seçin</option><option v-for="d in districts" :key="d.id" :value="d.id">{{ d.name }}</option></select></div>
<div class="field"><label>Mahalle</label><select v-model.number="neighborhoodId" :disabled="!districtId"><option :value="undefined">Mahalle seçin</option><option v-for="n in neighborhoods" :key="n.id" :value="n.id">{{ n.name }}</option></select></div>
<div class="field"><label>Gayrimenkul türü</label><select v-model="propertyType"><option value="apartment">Daire</option><option value="detached_house">Müstakil ev</option><option value="villa">Villa</option><option value="residential_zoned_land">Konut imarlı arsa</option><option value="commercial_zoned_land">Ticari imarlı arsa</option><option value="farmland">Tarla</option></select></div>
<div v-if="isResidential" class="field"><label>Alan türü</label><select v-model="areaType"><option value="net">Net m²</option><option value="gross">Brüt m²</option></select></div>
<div class="field"><label>{{ isResidential ? 'Alan (m²)' : 'Parsel alanı (m²)' }}</label><input v-model.number="area" type="number" min="1" max="1000000" step="1"></div>
<div v-if="isResidential" class="field"><label>Oda düzeni (isteğe bağlı)</label><select v-model.number="roomCount"><option :value="undefined">Farketmez</option><option :value="1">1+0 (stüdyo)</option><option :value="2">1+1</option><option :value="3">2+1</option><option :value="4">3+1</option><option :value="5">4+1</option><option :value="6">5+1</option></select></div>
<button class="button button-primary" :disabled="loading || loadingLocations" @click="estimate">{{ loading?'Emsaller inceleniyor…':'Emsallere göre tahmin et' }}</button>
<p class="muted-note">Emsal karşılaştırmasında alanı yaklaşık %70–130 aralığında olan, aynı türdeki aktif ilanlar dikkate alınır; yeterli emsal yoksa kriterler kademeli gevşetilir. Hatalı görünen uç fiyatlar hesaba katılmaz.</p></section>
<section class="panel"><h2>Tahmin sonucu</h2><div v-if="!result && !loading" class="empty-state"><p>Sonucu görmek için konum ve alan bilgilerini girip tahmin oluşturun.</p></div><StatePanel v-else-if="loading" state="loading"/><template v-else-if="result"><div class="estimate-grid"><div class="estimate-card"><h3>Satılık tahmini</h3><p class="estimate-price">{{ result.sale_estimate?.estimated_price!=null?money(result.sale_estimate.estimated_price):'Yeterli emsal yok' }}</p><p class="muted-note">{{ result.sale_estimate?.low_estimate!=null?`${money(result.sale_estimate.low_estimate)} – ${money(result.sale_estimate.high_estimate)}`:'Satılık emsal bulunamadı' }}</p><p class="muted-note">{{ result.sale_estimate?.comparable_count||0 }} satılık emsal · {{ result.sale_estimate?.median_price_per_m2!=null?money(result.sale_estimate.median_price_per_m2):'—' }} / m²</p><p class="muted-note">{{ result.sale_estimate?.message }}</p></div><div class="estimate-card"><h3>Kiralık tahmini (aylık)</h3><p class="estimate-price">{{ result.rent_estimate?.estimated_price!=null?money(result.rent_estimate.estimated_price):'Yeterli emsal yok' }}</p><p class="muted-note">{{ result.rent_estimate?.low_estimate!=null?`${money(result.rent_estimate.low_estimate)} – ${money(result.rent_estimate.high_estimate)}`:'Kiralık emsal bulunamadı' }}</p><p class="muted-note">{{ result.rent_estimate?.comparable_count||0 }} kiralık emsal · {{ result.rent_estimate?.median_price_per_m2!=null?money(result.rent_estimate.median_price_per_m2):'—' }} / m²</p><p class="muted-note">{{ result.rent_estimate?.message }}</p></div></div><p class="muted-note">{{ result.province }} / {{ result.district }} / {{ result.neighborhood }}. Satılık ve kiralık tahminleri ayrı emsal havuzlarından hesaplanır; kiralık sonuç aylık kira bedelidir.</p><h3 v-if="result.sale_estimate?.comparable_listings?.length">Satılık emsaller</h3><div v-if="result.sale_estimate?.comparable_listings?.length" class="table-wrap"><table><thead><tr><th>İlan fiyatı</th><th>Alan</th><th>Fiyat / m²</th></tr></thead><tbody><tr v-for="(c,i) in result.sale_estimate.comparable_listings" :key="i"><td>{{ money(c.asking_price) }}</td><td>{{ c.area_m2 }} m²</td><td>{{ money(c.price_per_m2) }}</td></tr></tbody></table></div><h3 v-if="result.rent_estimate?.comparable_listings?.length">Kiralık emsaller</h3><div v-if="result.rent_estimate?.comparable_listings?.length" class="table-wrap"><table><thead><tr><th>Aylık kira</th><th>Alan</th><th>Kira / m²</th></tr></thead><tbody><tr v-for="(c,i) in result.rent_estimate.comparable_listings" :key="i"><td>{{ money(c.asking_price) }}</td><td>{{ c.area_m2 }} m²</td><td>{{ money(c.price_per_m2) }}</td></tr></tbody></table></div></template></section></div></template>
<style scoped>.estimate-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.estimate-card{border:1px solid var(--border,#dce3ed);border-radius:14px;padding:16px;margin-bottom:12px}.estimate-price{font-size:24px;font-weight:750;color:var(--text,#162d4d);margin:12px 0}.muted-note{font-size:13px;color:var(--muted,#65738b);margin-top:14px;line-height:1.5}.field{margin-bottom:14px}.button{margin-top:8px}</style>
